WITH with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM sessions), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, CASE WHEN is_new_burst >= 1 THEN 'LARGE' ELSE 'SMALL' END AS is_new_burst_tier, CASE WHEN burst_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS burst_id_tier, ROUND(AVG(burst_id), 2) AS avg_burst_id, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, ROUND(SUM(is_new_burst) / NULLIF(COUNT(CASE WHEN browser = 'Chrome' THEN 1 END), 0), 2) AS is_new_burst_per_chrome FROM islands GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', started_at), CASE WHEN is_new_burst >= 1 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN burst_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('QUARTER', started_at), CASE WHEN is_new_burst >= 1 THEN 'LARGE' ELSE 'SMALL' END)) ORDER BY quarter_start DESC NULLS LAST
